#include "RegisterSourceHierarchyMatrix.h"
#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <stop_token>
using namespace dft::sequential;
static unsigned n=0;static void need(bool v,const char* m){++n;if(!v)throw std::runtime_error(m);}
static void bad(const auto& r,const char* m){need(!r&&r.error().code==hier::ErrorCode::BadRequest,m);}
static auto open(const char* f){hier::model::OpenOptions o;o.files={f};o.tops={"W_tree"};auto r=hier::Design::open(o);need(r.ok(),"open own tree");return std::move(r.value());}
static auto request(size_t count=3){RegisterScenarioRequest r;r.common.resolveLogic=true;for(size_t i=0;i<count;++i)r.scenarios.push_back({"S"+std::to_string(i),{{{"W_tree.mode",0},bool(i%2)}}});return r;}
static auto chain(hier::Design& d,const std::string& ref,const std::string& scope){auto a=d.ancestors(ref);need(a.ok(),"independent public ancestors");std::vector<hier::model::InstInfo> out;bool included=false;for(const auto& x:*a){if(x.ref==scope)included=true;if(included)out.push_back(x);}auto self=d.instance(ref);need(self.ok(),"independent public instance");need(included||ref==scope,"scope belongs to actual ancestor chain");out.push_back(*self);return out;}
static void checkTree(hier::Design& d,const RegisterStatistics& s,const RegisterSourceHierarchyReport& h){need(h.scope.has_value(),"scope metadata");for(size_t ci=0;ci<h.comparisons.size();++ci){const auto& c=h.comparisons[ci];const auto& ic=h.analysis.comparisons[ci];for(const auto& node:c.nodes){auto ch=chain(d,node.info.ref,h.scope->ref);const auto& x=ch.back();need(node.info.ref==x.ref&&node.info.name==x.name&&node.info.path==x.path&&node.info.pathText==x.pathText&&node.info.def==x.def&&node.info.defName==x.defName&&node.info.kind==x.kind&&node.info.childCount==x.childCount&&node.info.hasParamOverrides==x.hasParamOverrides,"owned navigation metadata exactly Core");need(node.depth==ch.size()-1&&(ch.size()==1?!node.parent:node.parent&&*node.parent==ch[ch.size()-2].ref),"parent and depth from actual Core chain");std::vector<size_t> members;for(size_t i=0;i<ic.instances.size();++i){auto local=chain(d,s.instances[ic.instances[i].instance].info.ref,h.scope->ref);if(std::any_of(local.begin(),local.end(),[&](const auto& info){return info.ref==node.info.ref;}))members.push_back(i);}need(node.members==members,"subtree membership follows authoritative ancestors");}}}
int main(int argc,char** argv){try{
 need(argc==2,"fixture");auto d=open(argv[1]);StatisticsRequest rq;rq.scope="W_tree";rq.recursive=true;auto st=registerStatistics(*d,rq);need(st.ok()&&st->complete&&st->totals.coveredBits==18,"root2 plus four independent4-bit instances");auto req=request();std::stop_source stop;stop.request_stop();
 auto a=compareRegisterSourceImpact(*d,*st,req,{},stop.get_token());need(!a&&a.error().code==hier::ErrorCode::Cancelled,"impact pre-cancel");auto b=compareRegisterSourceHierarchy(*d,*st,req,{},stop.get_token());need(!b&&b.error().code==hier::ErrorCode::Cancelled,"hierarchy pre-cancel");auto c=compareRegisterSourceHierarchyMatrix(*d,*st,req,{},stop.get_token());need(!c&&c.error().code==hier::ErrorCode::Cancelled,"matrix pre-cancel");
 RegisterSourceImpactLimits il;il.maxInstances=0;bad(compareRegisterSourceImpact(*d,*st,req,il),"impact bad limits");RegisterSourceHierarchyLimits hl;hl.maxQueries=0;bad(compareRegisterSourceHierarchy(*d,*st,req,hl),"hierarchy bad limits");RegisterSourceHierarchyMatrixLimits ml;ml.maxInputNodes=0;bad(compareRegisterSourceHierarchyMatrix(*d,*st,req,ml),"matrix bad limits");auto wrong=*st;wrong.snapshot.snapshotId+="wrong";
 bad(compareRegisterSourceImpact(*d,wrong,req),"impact snapshot mismatch");bad(compareRegisterSourceHierarchy(*d,wrong,req),"hierarchy snapshot mismatch");bad(compareRegisterSourceHierarchyMatrix(*d,wrong,req),"matrix snapshot mismatch");wrong=*st;wrong.definitions[wrong.instances[0].definition].name+="wrong";bad(compareRegisterSourceImpact(*d,wrong,req),"used definition metadata rejects contradiction");wrong=*st;wrong.instances[0].info.pathText+="wrong";bad(compareRegisterSourceHierarchy(*d,wrong,req),"same ref different canonical path rejected");
 auto br=req;br.scenarios[1].inputValues[0].input.path="missing";need(!compareRegisterSourceImpact(*d,*st,br),"impact second context no half success");need(!compareRegisterSourceHierarchy(*d,*st,br),"hierarchy second context no half success");need(!compareRegisterSourceHierarchyMatrix(*d,*st,br),"matrix second context no half success");
 auto im=compareRegisterSourceImpact(*d,*st,req);need(im.ok()&&im->complete&&im->comparisons[0].instances.size()==5&&im->comparisons[0].definitions.size()==2,"five local state instances/two used definitions");need(im->comparisons[0].totals.coveredBits==18&&im->comparisons[0].totals.changedBits==16&&im->comparisons[0].totals.retainedOnlyBits==2,"impact18/16/2 not shared-body deduplication");
 auto h=compareRegisterSourceHierarchy(*d,*st,req);need(h.ok()&&h->complete&&h->comparisons[0].nodes.size()==6,"six real instance nodes, generate not node");checkTree(*d,*st,*h);for(const auto& node:h->comparisons[0].nodes){if(node.info.name=="tail"||node.info.name=="edge.case")need(node.depth==1,"generate/escaped name are direct instance children");if(node.info.name=="grp")need(!node.local&&node.counts.coveredBits==8,"nonlocal ancestor keeps both4-bit children");}need(h->comparisons[0].totals.coveredBits==18&&h->comparisons[1].totals.retainedOnlyBits==18,"root total once and0/1/0 isolation");auto eight=compareRegisterSourceHierarchy(*d,*st,request(8));need(eight.ok()&&eight->complete&&eight->queries==h->queries&&eight->ancestorEntries==h->ancestorEntries,"topology navigation cached across contexts only");
 auto matrix=compareRegisterSourceHierarchyMatrix(*d,*st,req);need(matrix.ok()&&matrix->complete&&matrix->comparisons[0].rows.size()==12&&matrix->comparisons[1].rows.size()==6,"source/node row domain12 then6");need(std::string(sourceHierarchyRoleName(SourceHierarchyRole::Added))=="added"&&std::string(sourceHierarchyRoleName(SourceHierarchyRole::Removed))=="removed"&&std::string(sourceHierarchyRoleName(SourceHierarchyRole::Retained))=="retained","public role names");
 il={};il.maxInstances=1;auto pi=compareRegisterSourceImpact(*d,*st,req,il);need(pi.ok()&&!pi->complete&&pi->comparisons[0].instances.size()==1&&pi->comparisons[0].definitions.size()==1,"instance/definition simultaneous prefix");hl={};hl.maxNodes=1;auto ph=compareRegisterSourceHierarchy(*d,*st,req,hl);need(ph.ok()&&!ph->complete&&ph->comparisons[0].nodes.size()==1&&ph->comparisons[0].totals.coveredBits==18,"root keeps full provided member domain when children capped");hl={};hl.maxMembers=1;auto pm=compareRegisterSourceHierarchy(*d,*st,req,hl);need(pm.ok()&&!pm->complete&&pm->comparisons[0].nodes.empty()&&pm->comparisons[0].totals.coveredBits==0,"no half root/member counts");ml={};ml.maxInputNodes=1;auto px=compareRegisterSourceHierarchyMatrix(*d,*st,req,ml);need(px.ok()&&!px->complete&&!px->comparisons[0].inputCollected&&px->rows==0&&px->inputNodes==0&&px->inputMembers==0,"matrix no partial collection/count commit");ml={};ml.maxMembers=1;auto pr=compareRegisterSourceHierarchyMatrix(*d,*st,req,ml);need(pr.ok()&&!pr->complete&&pr->comparisons[0].rows.empty()&&pr->members==0,"matrix pair member/count publication atomic");
 rq.scope="W_tree.grp";auto ls=registerStatistics(*d,rq);need(ls.ok()&&ls->complete,"local scope statistics");auto local=compareRegisterSourceHierarchy(*d,*ls,req);need(local.ok()&&local->complete&&local->comparisons[0].nodes.size()==3&&local->comparisons[0].totals.coveredBits==8,"local scope three nodes8 bits");checkTree(*d,*ls,*local);
 d.reset();st=hier::Error{hier::ErrorCode::BadRequest,"released"};ls=hier::Error{hier::ErrorCode::BadRequest,"released"};need(!im->comparisons[0].instances[0].members.empty()&&h->scope->name=="W_tree"&&matrix->comparisons[0].rows.size()==12&&!matrix->comparisons[0].rows[0].members.empty(),"all nested/new containers owned after Design and statistics release");std::cout<<"{\"passed\":true,\"assertions\":"<<n<<"}\n";return 0;
 }catch(const std::exception& e){std::cerr<<"after "<<n<<" assertions: "<<e.what()<<'\n';return 1;}}
